WITH with_windows AS (SELECT *, AVG(quantity) OVER (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS quantity_avg_3_prior, PERCENT_RANK() OVER w_hist AS quantity_percent_rank, ROW_NUMBER() OVER (ORDER BY unit_price DESC, id) AS event_seq, SUM(unit_price) OVER (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_unit_price FROM order_items WINDOW w_hist AS (ORDER BY quantity NULLS LAST)) SELECT product_id, order_id, PERCENTILE_APPROX(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, COUNT(DISTINCT order_id) AS distinct_order_ids, APPROX_PERCENTILE(quantity_percent_rank, ARRAY(0.25, 0.5, 0.75)) AS quantity_percent_rank_quartiles, ROUND(AVG(event_seq), 2) AS avg_event_seq FROM with_windows GROUP BY ROLLUP (product_id, order_id) ORDER BY distinct_order_ids DESC NULLS LAST;
